// Command create_mod produces a spec-compliant Go module zip from a source
// directory using golang.org/x/mod/zip.CreateFromDir — the same implementation
// the module proxy uses, so the member set matches by construction.
//
// It is built as its own module in a temporary directory outside this
// checkout so that building it never mutates golang.org/x/mod's own go.mod.
package main

import (
	"log"
	"os"

	"golang.org/x/mod/module"
	"golang.org/x/mod/zip"
)

func main() {
	if len(os.Args) != 5 {
		log.Fatal("usage: create_mod <module-path> <version> <source-dir> <output-zip>")
	}
	m := module.Version{Path: os.Args[1], Version: os.Args[2]}
	f, err := os.Create(os.Args[4])
	if err != nil {
		log.Fatal(err)
	}
	defer f.Close()
	if err := zip.CreateFromDir(f, m, os.Args[3]); err != nil {
		log.Fatal(err)
	}
	log.Printf("created module zip: %s", os.Args[4])
}
